+import { claimNext } from "./jobs.ts";
+
+export const createApi = (app: any): void => {
+  app.get("/api/jobs/next", async (req: any, res: any) => {
+    const job = await claimNext();
+    if (job === null) {
+      return res.status(204).send();
+    }
+    res.json({ id: job.id, payload: job.payload });
+  });
+};
