+export interface JobEvent {
+  type: "job.ready";
+  jobId: string;
+  payload: string;
+}
+
+export interface EventPublisher {
+  publish(event: JobEvent): Promise<void>;
+}
+
+class RedisPublisher implements EventPublisher {
+  private client: any;
+
+  constructor(client: any) {
+    this.client = client;
+  }
+
+  async publish(event: JobEvent): Promise<void> {
+    await this.client.publish("jobs", JSON.stringify(event));
+  }
+}
+
+class LogPublisher implements EventPublisher {
+  async publish(event: JobEvent): Promise<void> {
+    console.log(`[EVENT] ${event.type}:`, event);
+  }
+}
+
+let publisher: EventPublisher | null = null;
+
+export const initPublisher = (impl: EventPublisher): void => {
+  publisher = impl;
+};
+
+export const publishJobReady = async (jobId: string, payload: string): Promise<void> => {
+  if (!publisher) {
+    throw new Error("Event publisher not initialized");
+  }
+  await publisher.publish({
+    type: "job.ready",
+    jobId,
+    payload,
+  });
+};
+
+export const createRedisPublisher = (client: any): EventPublisher => {
+  return new RedisPublisher(client);
+};
+
+export const createLogPublisher = (): EventPublisher => {
+  return new LogPublisher();
+};
